package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class MeetingActionsDialog {
 static void show(MainActivity host,String id){new Thread(()->{try{JSONObject data=MeetingActions.preview(host,id);JSONArray items=data.getJSONArray("items");String[] labels=new String[items.length()];for(int i=0;i<labels.length;i++)labels[i]=items.getJSONObject(i).getString("text");host.runOnUiThread(()->{if(host.isDestroyed())return;new AlertDialog.Builder(host).setTitle(labels.length==0?"保留候補は見つかりませんでした":"要約からの保留候補（自動登録しません）").setItems(labels,(d,index)->{EditText input=new EditText(host);input.setText(labels[index]);input.setMaxLines(8);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(800)});new AlertDialog.Builder(host).setTitle("保留する内容を確認・編集").setMessage("要約の記述です。日時や担当者の正確さを確認してください。予定は登録しません。").setView(input).setPositiveButton("受信箱に保留保存",(q,w)->new Thread(()->{String message;try{JSONObject result=MeetingActions.save(host,id,data.getString("sourceHash"),index,input.getText().toString());message=result.optBoolean("duplicate")?"この候補はすでに保留保存済みです":"受信箱に保留しました。予定は登録していません";}catch(Exception e){message="保存できませんでした。候補を開き直してください";}final String value=message;host.runOnUiThread(()->{if(!host.isDestroyed()){host.refreshInboxSummaryNow();new AlertDialog.Builder(host).setMessage(value).setPositiveButton("閉じる",null).show();}});},"MeetingToInbox").start()).setNegativeButton("閉じる",null).show();}).setPositiveButton("閉じる",null).show();});}catch(Exception e){host.runOnUiThread(()->Toast.makeText(host,"保存済み要約の候補を取得できません",Toast.LENGTH_LONG).show());}},"MeetingActions").start();}
 private MeetingActionsDialog(){}
}
